(window.CARDS = window.CARDS || {}).character = [{"name":"Гарри Поттер","emoji":"⚡","meta":["«Гарри Поттер»","юный волшебник","1997"],"description":"Мальчик-сирота, который в одиннадцать лет узнаёт, что он волшебник, и отправляется учиться в школу Хогвартс. Всю жизнь его преследует тёмный маг Волан-де-Морт, убивший его родителей, а на лбу у героя остался шрам в виде молнии.","fact":"Роль Гарри в фильмах сыграл Дэниэл Рэдклифф, которому на момент начала съёмок первой картины было одиннадцать лет.","wiki_en":"Harry Potter (character)"},{"name":"Гермиона Грейнджер","emoji":"📚","meta":["«Гарри Поттер»","отличница-волшебница","1997"],"description":"Одна из самых способных студенток Хогвартса, при этом родившаяся в семье обычных людей — маглов. Гермиона отличается острым умом, любовью к книгам и верностью друзьям, а её знания не раз спасают Гарри Поттера и Рона Уизли от опасности.","fact":"В фильмах роль Гермионы сыграла Эмма Уотсон, прошедшая кастинг ещё будучи школьницей.","wiki_en":"Hermione Granger"},{"name":"Северус Снегг","emoji":"🧪","meta":["«Гарри Поттер»","профессор зельеварения","1997"],"description":"Мрачный и язвительный профессор зельеварения в Хогвартсе, чьё истинное отношение к Гарри Поттеру долго остаётся загадкой. За внешней холодностью скрывается сложная судьба, тесно связанная с прошлым родителей мальчика.","fact":"Актёр Алан Рикман знал главную тайну персонажа задолго до выхода финальных книг — ему рассказала сама Роулинг.","wiki_en":"Severus Snape"},{"name":"Лорд Волан-де-Морт","emoji":"🐍","meta":["«Гарри Поттер»","тёмный волшебник","1997"],"description":"Самый могущественный тёмный волшебник своего времени, стремящийся к бессмертию и власти над магическим миром. Его имя большинство волшебников боятся произносить вслух, называя его просто Тёмным Лордом или Тем-Кого-Нельзя-Называть.","fact":"Актёру Рэйфу Файнсу для роли пришлось сниматься без кончика носа — его убирали с помощью компьютерной графики.","wiki_en":"Lord Voldemort"},{"name":"Альбус Дамблдор","emoji":"🧙","meta":["«Гарри Поттер»","директор Хогвартса","1997"],"description":"Директор школы Хогвартс и один из сильнейших волшебников мира, известный своей мудростью и некоторой эксцентричностью. Он выступает наставником Гарри Поттера и одним из немногих, кого по-настоящему опасается Волан-де-Морт.","fact":"Первым исполнителем роли Дамблдора в кино был Ричард Харрис, а после его смерти персонажа сыграл Майкл Гэмбон.","wiki_en":"Albus Dumbledore"},{"name":"Фродо Бэггинс","emoji":"💍","meta":["«Властелин колец»","хоббит-хранитель","1954"],"description":"Скромный хоббит из Шира, на плечи которого ложится задача уничтожить Кольцо Всевластия. Долгий и опасный путь через Средиземье к жерлу вулкана Ородруин становится для него тяжелейшим испытанием, меняющим его характер навсегда.","fact":"В экранизации Питера Джексона роль Фродо сыграл Элайджа Вуд, снимавшийся в кино с раннего детства.","wiki_en":"Frodo Baggins"},{"name":"Гэндальф","emoji":"🧙‍♂️","meta":["«Властелин колец»","волшебник-странник","1937"],"description":"Могущественный маг-странник, помогающий народам Средиземья в борьбе против тьмы. Впервые появляется ещё в «Хоббите» как таинственный проводник Бильбо Бэггинса, а позже становится духовным вождём Братства Кольца.","fact":"Прообразом внешности Гэндальфа, по словам самого Толкина, послужила открытка с изображением горного старика-странника.","wiki_en":"Gandalf"},{"name":"Голлум","emoji":"🐟","meta":["«Властелин колец»","раздвоенное существо","1937"],"description":"Некогда хоббитоподобное существо, изуродованное долгим владением Кольцом Всевластия, которое он называет «моя прелесть». В нём одновременно борются жалкое, коварное создание и слабые остатки его прежней, доброй личности.","fact":"Голлума в фильмах Питера Джексона сыграл Энди Серкис с помощью технологии захвата движения.","wiki_en":"Gollum"},{"name":"Арагорн","emoji":"⚔️","meta":["«Властелин колец»","наследник престола","1954"],"description":"Скиталец, известный также как Бродяжник, который оказывается законным наследником древнего королевства Гондор. Он ведёт Братство Кольца через опасности Средиземья и в итоге становится королём, объединившим людей против сил тьмы.","fact":"Роль Арагорна досталась Вигго Мортенсену почти в последний момент, когда съёмки трилогии уже начались.","wiki_en":"Aragorn"},{"name":"Леголас","emoji":"🏹","meta":["«Властелин колец»","эльф-лучник","1954"],"description":"Принц лесных эльфов и виртуозный лучник, один из членов Братства Кольца. Его меткость, острое зрение и неожиданная дружба с гномом Гимли, несмотря на давнюю вражду их народов, — одни из ярких моментов истории.","fact":"Ради роли актёр Орландо Блум специально учился стрельбе из лука, верховой езде и фехтованию.","wiki_en":"Legolas"},{"name":"Дарт Вейдер","emoji":"🫁","meta":["«Звёздные войны»","тёмный лорд ситхов","1977"],"description":"Могучий воин тёмной стороны Силы, узнаваемый по чёрной маске и тяжёлому механическому дыханию. Некогда рыцарь-джедай, он перешёл на сторону Империи и стал одним из самых узнаваемых злодеев в истории кино.","fact":"Голос Дарта Вейдера в оригинальной трилогии озвучил Джеймс Эрл Джонс, хотя в кадре персонажа играл другой актёр.","wiki_en":"Darth Vader"},{"name":"Люк Скайуокер","emoji":"🌅","meta":["«Звёздные войны»","рыцарь-джедай","1977"],"description":"Юноша с пустынной планеты Татуин, который узнаёт о своём предназначении и становится одним из последних рыцарей-джедаев. Его путь взросления и борьбы против Империи — центральная сюжетная линия оригинальной трилогии.","fact":"Сцена, где Люк смотрит на закат двух солнц Татуина, стала одним из самых узнаваемых кадров всей саги.","wiki_en":"Luke Skywalker"},{"name":"Йода","emoji":"🟢","meta":["«Звёздные войны»","мастер-джедай","1980"],"description":"Один из старейших и мудрейших джедаев галактики, обучающий молодых учеников владению Силой, несмотря на свой небольшой рост. Его необычная манера речи и лаконичные афоризмы стали узнаваемой частью мировой поп-культуры.","fact":"Куклой Йоды в оригинальных фильмах управлял и озвучивал Фрэнк Оз, известный также по работе с куклами Маппетов.","wiki_en":"Yoda"},{"name":"Хан Соло","emoji":"🚀","meta":["«Звёздные войны»","контрабандист-пилот","1977"],"description":"Дерзкий пилот и контрабандист, капитан корабля «Тысячелетний сокол», который поначалу действует лишь из корысти, но постепенно становится настоящим героем восстания против Империи. Его остроумие сделало его одним из самых любимых персонажей саги.","fact":"Роль Хана Соло сделала Харрисона Форда мировой звездой ещё до его участия в «Индиане Джонсе».","wiki_en":"Han Solo"},{"name":"Принцесса Лея","emoji":"👑","meta":["«Звёздные войны»","лидер повстанцев","1977"],"description":"Принцесса разрушенной Империей планеты Альдераан и одна из руководителей Альянса повстанцев. Решительная и бесстрашная, она сочетает дипломатические таланты с готовностью лично сражаться за свободу галактики.","fact":"Кэрри Фишер сыграла Лею в оригинальной трилогии и вернулась к этой роли почти через сорок лет — в «Пробуждении силы».","wiki_en":"Princess Leia"},{"name":"Чубакка","emoji":"🔫","meta":["«Звёздные войны»","воин-вуки","1977"],"description":"Рослый и невероятно сильный воин из народа вуки, верный друг и второй пилот Хана Соло на «Тысячелетнем соколе». Несмотря на устрашающий вид, он один из самых преданных и добродушных героев всей саги.","fact":"Чубакку в оригинальной трилогии сыграл актёр Питер Мэйхью, чей рост превышал два с лишним метра.","wiki_en":"Chewbacca"},{"name":"R2-D2","emoji":"🤖","meta":["«Звёздные войны»","дроид-астромеханик","1977"],"description":"Маленький дроид-астромеханик, преданный спутник героев саги, способный чинить корабли и хранить важнейшие секретные данные. Хотя он общается лишь звуковыми сигналами и свистом, его прекрасно понимают почти все персонажи.","fact":"В некоторых сценах оригинальной трилогии внутри костюма R2-D2 сидел актёр небольшого роста Кенни Бейкер.","wiki_en":"R2-D2"},{"name":"Грогу","emoji":"👶","meta":["«Мандалорец»","малыш из расы Йоды","2019"],"description":"Загадочный малыш из того же таинственного вида, что и мастер Йода, обладающий врождённой связью с Силой. Его находит и берёт под защиту воин-мандалорец, а трогательная дружба героя с подопечным стала главной темой сериала.","fact":"Ещё до объявления официального имени поклонники по всему миру называли персонажа просто «малыш Йода».","wiki_en":"Grogu"},{"name":"Человек-паук","emoji":"🕷️","meta":["Marvel","супергерой-паук","1962"],"description":"Обычный школьник Питер Паркер, получивший от укуса радиоактивного паука сверхчеловеческие способности — силу, ловкость и умение чувствовать опасность. Он сражается с преступностью Нью-Йорка, оставаясь в обычной жизни скромным парнем.","fact":"Создатели Человека-паука Стэн Ли и Стив Дитко хотели, чтобы у героя, в отличие от многих других, были самые обычные подростковые проблемы.","wiki_en":"Spider-Man"},{"name":"Железный человек","emoji":"🦾","meta":["Marvel","гений в броне","1963"],"description":"Миллиардер-изобретатель Тони Старк, создающий мощный боевой костюм, чтобы бороться со злом и искупить вину за собственное оружие, попавшее не в те руки. Его остроумие и технический гений сделали его одним из самых узнаваемых супергероев.","fact":"Роль Тони Старка в киновселенной Marvel сделала Роберта Дауни-младшего одним из самых высокооплачиваемых актёров мира.","wiki_en":"Iron Man"},{"name":"Капитан Америка","emoji":"🛡️","meta":["Marvel","солдат-суперсолдат","1941"],"description":"Хилый юноша Стив Роджерс, ставший благодаря экспериментальной сыворотке суперсолдатом и символом борьбы против фашизма во время Второй мировой войны. В современности он остаётся образцом воинской чести среди супергероев Marvel.","fact":"Капитан Америка был создан ещё до вступления США во Вторую мировую войну и с самого начала боролся с нацистами.","wiki_en":"Captain America"},{"name":"Тор","emoji":"⚡","meta":["Marvel","бог грома","1962"],"description":"Могучий асгардский бог грома, владеющий волшебным молотом Мьёльнир, поднять который способен лишь достойный. Гордый и вспыльчивый в начале своей истории, он постепенно учится мудрости и ответственности правителя.","fact":"Персонаж Marvel основан на скандинавском боге Торе, но со временем обзавёлся собственной, самостоятельной мифологией.","wiki_en":"Thor (Marvel Comics)"},{"name":"Халк","emoji":"💚","meta":["Marvel","зелёный гигант","1962"],"description":"Учёный Брюс Бэннер, который под воздействием гнева превращается в невероятно сильное зелёное существо, почти неуязвимое для обычного оружия. Внутренняя борьба между разумным человеком и разрушительным монстром — ключевая тема его истории.","fact":"Изначально в комиксах Халк был серым, но из-за трудностей с печатью цвет довольно быстро сменили на зелёный.","wiki_en":"Hulk"},{"name":"Чёрная вдова","emoji":"🖤","meta":["Marvel","шпионка-мстительница","1964"],"description":"Наташа Романофф — бывшая советская шпионка и убийца, перешедшая на сторону команды супергероев Мстителей. Она не обладает сверхспособностями, полагаясь в бою на боевые навыки, хитрость и годы разведывательной подготовки.","fact":"Роль Наташи Романофф в киновселенной Marvel сыграла Скарлетт Йоханссон начиная с фильма «Железный человек 2».","wiki_en":"Black Widow (Natasha Romanova)"},{"name":"Танос","emoji":"💜","meta":["Marvel","титан-завоеватель","1973"],"description":"Могущественный титан, одержимый идеей восстановить баланс во вселенной радикальным и жестоким способом. Обладая артефактами невероятной силы, он становится одним из самых масштабных противников, с которыми когда-либо сталкивались супергерои Marvel.","fact":"В фильмах киновселенной Marvel Таноса сыграл Джош Бролин, хотя большую часть образа создала компьютерная графика.","wiki_en":"Thanos"},{"name":"Локи","emoji":"🎭","meta":["Marvel","бог хитрости","1962"],"description":"Приёмный брат Тора и бог хитрости из скандинавской мифологии в версии Marvel, чьи мотивы вечно балансируют между злодейством и стремлением доказать собственную значимость. Его непредсказуемость сделала его одним из самых любимых антигероев киновселенной.","fact":"Актёр Том Хиддлстон получил роль Локи, изначально пробуясь на кастинге именно на роль Тора.","wiki_en":"Loki (Marvel Comics)"},{"name":"Дэдпул","emoji":"🗨️","meta":["Marvel","болтливый наёмник","1991"],"description":"Изуродованный экспериментами наёмник Уэйд Уилсон, получивший сверхбыструю регенерацию и своеобразное чувство юмора. В отличие от большинства супергероев он постоянно обращается напрямую к зрителю, ломая четвёртую стену.","fact":"Дэдпул появился как пародия на героя DC Дэтстроука: их настоящие имена — Уэйд Уилсон и Слэйд Уилсон — нарочно созвучны.","wiki_en":"Deadpool"},{"name":"Росомаха","emoji":"🗡️","meta":["Marvel","мутант-когти","1974"],"description":"Мутант Логан с регенеративными способностями, обострёнными чувствами и выдвижными когтями из сверхпрочного металла. Его вспыльчивый характер и полное потерь прошлое сделали его одним из самых популярных героев вселенной Marvel.","fact":"Роль Росомахи Хью Джекман играл почти два десятилетия — дольше, чем большинство актёров в других супергеройских франшизах.","wiki_en":"Wolverine (character)"},{"name":"Грут","emoji":"🌳","meta":["Marvel","древовидное существо","1960"],"description":"Похожее на дерево разумное существо-инопланетянин, способное произносить лишь фразу «Я — Грут», хотя собеседники прекрасно его понимают. Несмотря на скудную речь, он один из самых преданных и трогательных членов Стражей Галактики.","fact":"Голос Грута в киновселенной Marvel исполнил актёр Вин Дизель, произнося одну и ту же фразу с разными интонациями.","wiki_en":"Groot"},{"name":"Бэтмен","emoji":"🦇","meta":["DC","супергерой без сил","1939"],"description":"Миллиардер Брюс Уэйн, ставший ночным мстителем после гибели родителей от рук уличного грабителя. Не обладая сверхспособностями, он полагается на интеллект, боевые навыки и арсенал технологий, чтобы защищать Готэм от преступности.","fact":"Бэтмен — один из немногих культовых супергероев, у которого от природы нет никаких сверхъестественных способностей.","wiki_en":"Batman"},{"name":"Джокер","emoji":"🃏","meta":["DC","безумный преступник","1940"],"description":"Хаотичный преступный гений с раскрашенным белым лицом и зловещей улыбкой, главный противник Бэтмена в Готэме. Его истинное происхождение остаётся туманным, а сам он воплощает чистую анархию и непредсказуемость.","fact":"Роль Джокера приносила «Оскар» сразу двум актёрам — Хиту Леджеру и Хоакину Фениксу — за исполнение этого персонажа в разных фильмах.","wiki_en":"Joker (character)"},{"name":"Супермен","emoji":"🪐","meta":["DC","супергерой с Криптона","1938"],"description":"Инопланетянин Кал-Эл, отправленный ещё младенцем с гибнущей планеты Криптон на Землю, где обретает сверхчеловеческую силу, полёт и почти полную неуязвимость. Работая журналистом под именем Кларк Кент, он защищает мир, оставаясь символом надежды.","fact":"Супермен считается одним из первых супергероев в современном понимании — комикс о нём вышел ещё в 1938 году.","wiki_en":"Superman"},{"name":"Чудо-женщина","emoji":"🪢","meta":["DC","амазонка-воительница","1941"],"description":"Принцесса амазонок Диана, покинувшая родной остров Темискира, чтобы принести в мир людей справедливость и сострадание. Она сражается волшебным лассо правды и обладает нечеловеческой силой, оставаясь одной из первых по-настоящему культовых супергероинь.","fact":"Создатель Чудо-женщины Уильям Марстон также был одним из изобретателей раннего варианта детектора лжи.","wiki_en":"Wonder Woman"},{"name":"Харли Квинн","emoji":"🔨","meta":["DC","экс-психиатр Джокера","1992"],"description":"Бывший психиатр Готэмской лечебницы Харлин Квинзель, влюбившаяся в своего пациента Джокера и ставшая его сообщницей, а позже — независимой анти-героиней. Её эксцентричность, акробатика и чёрный юмор сделали её одной из самых популярных злодеек DC.","fact":"Харли Квинн впервые появилась не в комиксах, а в мультсериале «Бэтмен» в начале девяностых годов.","wiki_en":"Harley Quinn"},{"name":"Женщина-кошка","emoji":"🐱","meta":["DC","воровка в маске кошки","1940"],"description":"Ловкая грабительница Селина Кайл, действующая в Готэме под маской кошки и балансирующая между преступлением и симпатией к Бэтмену. Её отношения с Тёмным рыцарем — смесь соперничества, флирта и взаимного уважения.","fact":"Женщина-кошка появилась в комиксах о Бэтмене почти одновременно с самим Джокером, ещё в 1940 году.","wiki_en":"Catwoman"},{"name":"Джеймс Бонд","emoji":"🍸","meta":["«Джеймс Бонд»","британский разведчик","1953"],"description":"Элегантный агент британской разведки с позывным «007», сочетающий смертоносные навыки с безупречным стилем и невозмутимым хладнокровием. Его приключения против международных злодеев легли в основу одной из самых долговечных киносерий в истории.","fact":"Роль Джеймса Бонда в кино за десятилетия сыграли несколько разных актёров, начиная с Шона Коннери.","wiki_en":"James Bond"},{"name":"Индиана Джонс","emoji":"🤠","meta":["«Индиана Джонс»","археолог-авантюрист","1981"],"description":"Профессор археологии, который в свободное от лекций время добывает древние артефакты в опасных экспедициях по всему миру. Его фирменные шляпа и кнут стали одними из самых узнаваемых атрибутов в истории приключенческого кино.","fact":"Роль Индианы Джонса на протяжении десятилетий бессменно играл Харрисон Форд.","wiki_en":"Indiana Jones"},{"name":"Терминатор T-800","emoji":"🤖","meta":["«Терминатор»","робот-убийца","1984"],"description":"Киборг-андроид, присланный из будущего с металлическим скелетом под живой тканью, способный выполнять задание несмотря ни на что. В зависимости от фильма он выступает то безжалостным убийцей, то защитником людей.","fact":"Фраза I'll be back не задумывалась как крылатая — визитной карточкой персонажа она стала уже после выхода фильма.","wiki_en":"Terminator (character)"},{"name":"Рокки Бальбоа","emoji":"🥊","meta":["«Рокки»","боксёр из Филадельфии","1976"],"description":"Скромный боксёр-любитель из Филадельфии, получающий неожиданный шанс сразиться с чемпионом мира. История его упорства, тренировок и веры в себя стала символом преодоления обстоятельств для нескольких поколений зрителей.","fact":"Сценарий о Рокки Сильвестр Сталлоне написал сам, чтобы получить главную роль, хотя студии предлагали снять фильм с другими звёздами.","wiki_en":"Rocky Balboa"},{"name":"Джон Рэмбо","emoji":"🪖","meta":["«Рэмбо»","ветеран-спецназовец","1972"],"description":"Ветеран Вьетнамской войны Джон Рэмбо, чьи армейские навыки выживания и боя оборачиваются жестоким столкновением с властями мирного маленького городка. Персонаж стал символом тяжёлой судьбы солдат, вернувшихся с войны в равнодушное общество.","fact":"Персонаж родился не в кино: сначала был роман Дэвида Моррелла «Первая кровь», а экранизация с Сильвестром Сталлоне вышла десятью годами позже.","wiki_en":"John Rambo"},{"name":"Джон Уик","emoji":"🐕","meta":["«Джон Уик»","киллер на пенсии","2014"],"description":"Легендарный наёмный убийца, пытавшийся отойти от дел после потери жены, но вынужденный вернуться в мир криминала. Его хладнокровие, боевые навыки и стремительные перестрелки сделали серию фильмов эталоном современного экшена.","fact":"Актёр Киану Ривз лично выполнял значительную часть трюков и стрельбы, готовясь к роли несколько месяцев.","wiki_en":"John Wick (character)"},{"name":"Нео","emoji":"💊","meta":["«Матрица»","избранный хакер","1999"],"description":"Программист Томас Андерсон, узнающий, что привычный мир — это компьютерная симуляция, и получающий шанс освободить человечество. Выбор между синей и красной таблеткой стал одним из самых узнаваемых образов в истории кино.","fact":"Роль Нео сыграл Киану Ривз, а боевую хореографию фильма ставили мастера гонконгского кино.","wiki_en":"Neo (The Matrix)"},{"name":"Эллен Рипли","emoji":"👩‍🚀","meta":["«Чужой»","выжившая в космосе","1979"],"description":"Офицер грузового космического корабля, единственная сумевшая противостоять смертоносному инопланетному хищнику. Её хладнокровие и решительность сделали её одной из первых по-настоящему сильных героинь научно-фантастического кино.","fact":"Сигурни Уивер была номинирована на «Оскар» за роль Рипли в продолжении «Чужие» — редкий случай для фантастического боевика.","wiki_en":"Ellen Ripley"},{"name":"Марти Макфлай","emoji":"⏰","meta":["«Назад в будущее»","путешественник во времени","1985"],"description":"Обычный старшеклассник, случайно отправляющийся на модифицированном автомобиле в прошлое своих родителей. Ему приходится и наладить их знакомство, и не нарушить ход истории, пока друг-изобретатель ищет способ вернуть его домой.","fact":"Машиной времени DeLorean стал ещё на стадии сценария: в ранней версии её роль играл обычный холодильник.","wiki_en":"Marty McFly"},{"name":"Форрест Гамп","emoji":"🍫","meta":["«Форрест Гамп»","простодушный южанин","1986"],"description":"Добродушный уроженец Алабамы, который вопреки ограниченным умственным способностям становится невольным свидетелем и участником главных событий американской истории двадцатого века. Его искренность и верная любовь к Дженни трогают зрителей уже десятилетиями.","fact":"Знаменитую фразу про коробку шоколадных конфет придумал не автор романа, а сценарист фильма.","wiki_en":"Forrest Gump"},{"name":"Капитан Джек Воробей","emoji":"🏴‍☠️","meta":["«Пираты Карибского моря»","хитрый пират-капитан","2003"],"description":"Экстравагантный и вечно нетрезвый капитан «Чёрной жемчужины», выкручивающийся из любых передряг с помощью хитрости, обаяния и удачи. Его шаткая походка и непредсказуемые решения стали визитной карточкой всей франшизы.","fact":"Джонни Депп признавался, что создавал образ персонажа, вдохновляясь манерами музыканта Кита Ричардса.","wiki_en":"Jack Sparrow"},{"name":"Ганнибал Лектер","emoji":"🧠","meta":["романы Томаса Харриса","маньяк-психиатр","1981"],"description":"Блестящий психиатр с изощрённым интеллектом и утончённым вкусом, скрывающий за изысканными манерами склонность к чудовищным преступлениям. Его вынужденное сотрудничество со следователями ради поимки другого убийцы стало основой культового триллера.","fact":"Роль Ганнибала Лектера принесла Энтони Хопкинсу «Оскар», хотя его экранное время в фильме оказалось совсем небольшим.","wiki_en":"Hannibal Lecter"},{"name":"Тайлер Дёрден","emoji":"🧼","meta":["«Бойцовский клуб»","харизматичный анархист","1996"],"description":"Дерзкий и харизматичный торговец мылом, создающий подпольный бойцовский клуб как протест против потребительского общества. Его философия саморазрушения и свободы от вещей превращает обычных мужчин в участников радикального движения.","fact":"Персонаж впервые появился в романе Чака Паланика, а культовым его сделала экранизация Дэвида Финчера.","wiki_en":"Tyler Durden"},{"name":"Вито Корлеоне","emoji":"🐈","meta":["«Крёстный отец»","глава мафиозной семьи","1969"],"description":"Уважаемый и грозный глава итало-американской мафиозной семьи, придерживающийся собственного жёсткого кодекса чести и справедливости. Его спокойная властность и знаменитая хриплая речь стали образцом для бесчисленных подражаний в кино.","fact":"Роль Вито Корлеоне принесла Марлону Брандо «Оскар», от которого актёр демонстративно отказался.","wiki_en":"Vito Corleone"},{"name":"Тони Монтана","emoji":"🚬","meta":["«Лицо со шрамом»","кубинский наркобарон","1983"],"description":"Амбициозный кубинский эмигрант, который жестоким и стремительным путём поднимается на вершину наркоимперии Майами. Его безудержная жажда власти и знаменитая финальная реплика сделали его культовой фигурой криминального кино.","fact":"Роль Тони Монтаны сыграл Аль Пачино, специально работавший над кубинским акцентом персонажа.","wiki_en":"Tony Montana"},{"name":"Шерлок Холмс","emoji":"🔍","meta":["Артур Конан Дойл","гениальный сыщик","1887"],"description":"Проницательный лондонский детектив-консультант, раскрывающий самые запутанные преступления благодаря дедукции и вниманию к мельчайшим деталям. Его дружба с доктором Ватсоном и трубка с двухкозырьковой шляпой стали символом классического детектива.","fact":"Артур Конан Дойл пытался убить Холмса в одном из рассказов, но был вынужден вернуть героя к жизни под давлением читателей.","wiki_en":"Sherlock Holmes"},{"name":"Доктор Ватсон","emoji":"🩺","meta":["Артур Конан Дойл","верный друг-врач","1887"],"description":"Военный врач в отставке, ставший соседом и постоянным спутником Шерлока Холмса в его расследованиях. Именно от его лица ведётся большинство историй о сыщике, а его практичность оттеняет эксцентричную гениальность друга.","fact":"Имя рассказчика — доктора Ватсона — со временем стало нарицательным для верного помощника гениального специалиста.","wiki_en":"Dr. Watson"},{"name":"Эркюль Пуаро","emoji":"🥚","meta":["Агата Кристи","бельгийский детектив","1920"],"description":"Эксцентричный бельгийский сыщик с пышными усами, полагающийся на «маленькие серые клеточки» своего ума, а не на грубую физическую силу. Его аккуратность и любовь к порядку помогают распутывать самые изощрённые преступления в романах Агаты Кристи.","fact":"Со временем Агата Кристи стала уставать от своего персонажа, называя его порой несносным и надоедливым типом.","wiki_en":"Hercule Poirot"},{"name":"Граф Дракула","emoji":"🦇","meta":["Брэм Стокер","вампир-аристократ","1897"],"description":"Трансильванский граф-вампир, живущий столетиями за счёт крови людей и способный превращаться в летучую мышь. Его образ, созданный Брэмом Стокером, стал первоисточником почти всей современной вампирской мифологии в культуре.","fact":"Прототипом графа отчасти считается валашский правитель пятнадцатого века Влад Цепеш, известный своей жестокостью.","wiki_en":"Dracula"},{"name":"Чудовище Франкенштейна","emoji":"⚡","meta":["Мэри Шелли","искусственный великан","1818"],"description":"Безымянное существо, собранное учёным Виктором Франкенштейном из частей мёртвых тел и оживлённое неизвестным науке способом. Несмотря на пугающий вид, в романе Мэри Шелли он оказывается страдающим и одиноким созданием, отвергнутым собственным творцом.","fact":"В массовой культуре имя создателя — Франкенштейн — часто ошибочно закрепилось за самим чудовищем.","wiki_en":"Frankenstein's monster"},{"name":"Кинг-Конг","emoji":"🦍","meta":["«Кинг-Конг»","гигантская горилла","1933"],"description":"Огромная разумная горилла, обитающая на затерянном Острове черепа, которую пленяют и привозят в Нью-Йорк как диковинку. Его финальное восхождение на небоскрёб стало одним из самых узнаваемых образов в истории кино о монстрах.","fact":"В оригинальном фильме 1933 года Кинг-Конга оживляли с помощью покадровой анимации небольшой модели персонажа.","wiki_en":"King Kong"},{"name":"Годзилла","emoji":"🦖","meta":["Toho","гигантский монстр-ящер","1954"],"description":"Исполинское чудовище, пробуждённое ядерными испытаниями и способное дышать разрушительным атомным лучом. Первоначально созданный как метафора ужасов ядерного оружия, персонаж стал одним из самых узнаваемых монстров мирового кино.","fact":"Оригинальный костюм Годзиллы 1954 года весил десятки килограммов, и актёру внутри было крайне тяжело двигаться.","wiki_en":"Godzilla"},{"name":"Тарзан","emoji":"🌴","meta":["Эдгар Райс Берроуз","человек из джунглей","1912"],"description":"Английский аристократ по рождению, выросший среди обезьян в африканских джунглях после гибели родителей. Его невероятная физическая сила, знаменитый клич и дружба с животными сделали персонажа одним из главных героев приключенческой литературы и кино.","fact":"Знаменитый крик Тарзана в старых фильмах создавали, смешивая несколько разных звуковых дорожек.","wiki_en":"Tarzan"},{"name":"Зорро","emoji":"🗡️","meta":["Джонстон Маккалли","мститель в маске","1919"],"description":"Аристократ, который под маской и плащом защищает простых людей Калифорнии от несправедливости колониальных властей. Его фирменный знак — буква Z, вырезаемая шпагой, — стал символом благородного мстителя в маске для нескольких поколений.","fact":"Персонаж повлиял на образ Бэтмена: по канону комиксов Брюс Уэйн лишился родителей, возвращаясь с сеанса фильма о Зорро.","wiki_en":"Zorro"},{"name":"Робин Гуд","emoji":"🏹","meta":["английский фольклор","благородный разбойник","до XV века"],"description":"Легендарный благородный разбойник из Шервудского леса, грабящий богатых и раздающий добро бедным вместе со своей верной ватагой. Его противостояние жестокому шерифу Ноттингемскому и меткая стрельба из лука стали основой множества книг и фильмов.","fact":"Историки до сих пор спорят, существовал ли у легенды реальный исторический прототип.","wiki_en":"Robin Hood"},{"name":"Питер Пэн","emoji":"🧚","meta":["Джеймс Барри","вечный мальчик","1904"],"description":"Мальчик, который отказался взрослеть и живёт на волшебном острове Нетландия среди фей и пиратов. Он умеет летать и учит этому детей семьи Дарлинг, а его вечным противником выступает коварный капитан Крюк.","fact":"Имя персонажа со временем стало нарицательным для взрослых, психологически так и не повзрослевших людей.","wiki_en":"Peter Pan"},{"name":"Алиса из Страны чудес","emoji":"🐇","meta":["Льюис Кэрролл","любопытная девочка","1865"],"description":"Любознательная английская девочка, провалившаяся вслед за Белым Кроликом в нору и оказавшаяся в абсурдной волшебной стране. Её встречи с Чеширским Котом, Безумным Шляпником и Червонной Королевой стали классикой английской литературы нонсенса.","fact":"Автор Льюис Кэрролл придумал историю, катаясь на лодке с реальной девочкой по имени Алиса и её сёстрами.","wiki_en":"Alice (Alice's Adventures in Wonderland)"},{"name":"Винни-Пух","emoji":"🍯","meta":["Алан Милн","плюшевый медвежонок","1926"],"description":"Добродушный плюшевый медвежонок с опилками в голове и неизменной любовью к мёду, живущий в Стоакровом лесу. Вместе с друзьями — Пятачком, Иа-Иа и Тигрой — он переживает простые, но трогательные истории о дружбе.","fact":"Прообразом медвежонка стала настоящая плюшевая игрушка сына писателя Алана Милна.","wiki_en":"Winnie-the-Pooh"},{"name":"Карлсон","emoji":"🌀","meta":["Астрид Линдгрен","толстячок с пропеллером","1955"],"description":"Забавный и хвастливый толстячок, живущий на крыше стокгольмского дома и умеющий летать благодаря пропеллеру за спиной. Он становится тайным другом одинокого мальчика Малыша, вовлекая его в свои проделки и абсурдные выходки.","fact":"В шведском оригинале имя персонажа звучит иначе — Карлссон, с двумя «с» на конце.","wiki_en":"Karlsson-on-the-Roof"},{"name":"Пеппи Длинныйчулок","emoji":"🧦","meta":["Астрид Линдгрен","самая сильная девочка","1945"],"description":"Рыжая девочка с торчащими косичками, живущая одна в собственном доме вместе с обезьянкой и лошадью, без взрослых. Обладая невероятной физической силой и полным пренебрежением к условностям, она переворачивает жизнь тихого шведского городка.","fact":"Автор Астрид Линдгрен придумала историю для своей заболевшей дочери, а имя героини девочка выбрала сама.","wiki_en":"Pippi Longstocking"},{"name":"Маленький принц","emoji":"🌹","meta":["Антуан де Сент-Экзюпери","мальчик с астероида","1943"],"description":"Таинственный мальчик, прилетевший с крошечного астероида, где растёт единственная в его жизни роза. Его встреча с потерпевшим крушение в пустыне лётчиком превращается в философскую притчу о любви, дружбе и умении видеть главное.","fact":"Повесть Сент-Экзюпери стала одной из самых переводимых книг в мире, уступая по числу языков очень немногим изданиям.","wiki_en":"The Little Prince"},{"name":"Пиноккио","emoji":"🤥","meta":["Карло Коллоди","деревянный мальчик","1883"],"description":"Деревянная кукла, вырезанная старым столяром Джеппетто, которая мечтает стать настоящим живым мальчиком. Каждая его ложь заставляет нос удлиняться, а путь к обретению человечности проходит через череду поучительных злоключений.","fact":"В оригинальной итальянской сказке история значительно мрачнее и жёстче, чем в привычной диснеевской версии.","wiki_en":"Pinocchio"},{"name":"Золушка","emoji":"👠","meta":["европейский фольклор","добрая падчерица","XVII век"],"description":"Кроткая девушка, вынужденная терпеть унижения от мачехи и сводных сестёр, но с помощью доброй волшебницы попадающая на королевский бал. Потерянная хрустальная туфелька становится ключом к её счастливой судьбе в одном из самых известных сказочных сюжетов мира.","fact":"Похожие сюжеты о гонимой падчерице встречаются в фольклоре множества разных народов задолго до французской версии Перро.","wiki_en":"Cinderella"},{"name":"Белоснежка","emoji":"🍎","meta":["братья Гримм","прекраснейшая принцесса","1812"],"description":"Юная принцесса, чья красота вызывает зависть злой мачехи-королевы, приказывающей избавиться от падчерицы. Спасение у семерых гномов и отравленное яблоко сделали эту сказку одной из самых узнаваемых историй в мировой культуре.","fact":"«Белоснежка и семь гномов» стала первым полнометражным мультфильмом студии Disney и одним из первых в истории анимации.","wiki_en":"Snow White"},{"name":"Русалочка Ариэль","emoji":"🧜‍♀️","meta":["Disney","русалка-мечтательница","1989"],"description":"Любопытная юная русалка, мечтающая узнать человеческий мир и готовая пожертвовать ради этого своим голосом. Её коллекция человеческих вещиц и стремление к недостижимому на первый взгляд миру сделали её одной из самых любимых диснеевских принцесс.","fact":"Мультфильм Disney основан на сказке Ганса Христиана Андерсена, хотя финал в диснеевской версии значительно смягчён.","wiki_en":"Ariel (The Little Mermaid)"},{"name":"Эльза","emoji":"❄️","meta":["Disney «Холодное сердце»","королева со снежной магией","2013"],"description":"Старшая из двух сестёр-принцесс, обладающая врождённой магией льда и снега, которую в детстве она училась подавлять и скрывать. Её путь к принятию собственной силы и знаменитая песня о свободе стали культурным феноменом далеко за пределами детской аудитории.","fact":"Песня Эльзы из мультфильма получила «Оскар» за лучшую песню и стала одной из самых узнаваемых мелодий Disney.","wiki_en":"Elsa (Frozen)"},{"name":"Симба","emoji":"🦁","meta":["Disney «Король Лев»","молодой лев-наследник","1994"],"description":"Юный львёнок, наследник саванного престола, вынужденный после трагедии в семье бежать из родного прайда. Его взросление, дружба с Тимоном и Пумбой и в итоге возвращение, чтобы занять законное место короля, — классический сюжет о взрослении.","fact":"Сюжет мультфильма часто сравнивают с шекспировским «Гамлетом» — сходство отмечали и сами создатели картины.","wiki_en":"Simba"},{"name":"Микки Маус","emoji":"🐭","meta":["Disney","мышонок-символ студии","1928"],"description":"Жизнерадостный мышонок в красных шортах и больших жёлтых ботинках, ставший официальным символом всей компании Disney. Его первое озвученное появление в короткометражке с синхронным звуком считается важной вехой в истории анимации.","fact":"Изначально голосом Микки Мауса был сам создатель персонажа — Уолт Дисней.","wiki_en":"Mickey Mouse"},{"name":"Дональд Дак","emoji":"🦆","meta":["Disney","вспыльчивый селезень","1934"],"description":"Вспыльчивый и невезучий утёнок в матроске, чей узнаваемый скрипучий голос и частые вспышки гнева сделали его одним из самых популярных персонажей студии Disney. Несмотря на неудачи, он остаётся любимцем публики благодаря искренним эмоциям.","fact":"Голос Дональда Дака на протяжении десятилетий озвучивал один и тот же актёр — Кларенс Нэш.","wiki_en":"Donald Duck"},{"name":"Гуфи","emoji":"🐶","meta":["Disney","неуклюжий добряк","1932"],"description":"Долговязый и добродушный, но крайне неуклюжий антропоморфный пёс, друг Микки Мауса и Дональда Дака. Его нелепые падения и характерный возглас во время них стали одной из визитных карточек классической диснеевской анимации.","fact":"Прежде чем стать самостоятельным персонажем, Гуфи появлялся в мультфильмах просто как безымянный зритель на трибуне.","wiki_en":"Goofy"},{"name":"Багз Банни","emoji":"🥕","meta":["Warner Bros «Луни Тюнз»","хитрый кролик","1940"],"description":"Невозмутимый серый заяц с морковкой в лапах, неизменно перехитряющий своих незадачливых противников — охотника Элмера Фадда и многих других. Его фраза «Ну, что творится, док?» стала одной из самых цитируемых в истории мультипликации.","fact":"Манера Багза Банни грызть морковь во время разговора, по словам аниматоров, была отсылкой к сцене из фильма с Кларком Гейблом.","wiki_en":"Bugs Bunny"},{"name":"Том и Джерри","emoji":"🧀","meta":["MGM","кот и мышь-соперники","1940"],"description":"Домашний кот Том и хитрая мышь Джерри, бесконечно преследующие друг друга в чередующихся победах и поражениях почти без единого слова. Их безумные погони, полные слэпстик-трюков, давно стали классикой мировой мультипликации.","fact":"Несмотря на постоянные потасовки, мультсериал о них получил за годы существования несколько премий «Оскар» за короткий метр.","wiki_en":"Tom and Jerry"},{"name":"Скуби-Ду","emoji":"🐕","meta":["Hanna-Barbera","трусливый пёс-детектив","1969"],"description":"Крупный трусливый дог, обожающий печенье и постоянно попадающий в мистические переделки вместе с компанией друзей-подростков. Несмотря на страх перед привидениями, именно его случайная помощь часто помогает разоблачить очередного «монстра».","fact":"Имя персонажа навеяно строчкой из песни Фрэнка Синатры Strangers in the Night.","wiki_en":"Scooby-Doo (character)"},{"name":"Гомер Симпсон","emoji":"🍩","meta":["«Симпсоны»","недалёкий отец семейства","1989"],"description":"Работник атомной электростанции из вымышленного городка Спрингфилд, известный своей любовью к пончикам и пиву, а также редкой невезучестью. Его фирменный возглас при очередной неудаче стал одной из самых узнаваемых реплик в истории мультипликации.","fact":"Возглас Гомера «D'oh!» со временем официально внесли в английские толковые словари.","wiki_en":"Homer Simpson"},{"name":"Барт Симпсон","emoji":"🛹","meta":["«Симпсоны»","хулиганистый школьник","1989"],"description":"Десятилетний непоседа и главный хулиган школы Спрингфилда, обожающий розыгрыши и катание на скейтборде. Его фраза «Ай, карамба!» и фирменная стрижка сделали его одним из самых узнаваемых мультипликационных подростков в мире.","fact":"Голос Барта Симпсона на протяжении десятилетий бессменно исполняет актриса Нэнси Картрайт.","wiki_en":"Bart Simpson"},{"name":"Питер Гриффин","emoji":"🍺","meta":["«Гриффины»","недалёкий отец семейства","1999"],"description":"Взрывной и туповатый глава семейства из вымышленного городка Куахог, обожающий пиво и многосерийные потасовки с гигантским цыплёнком. Сериал построен на его абсурдных выходках и бесконечных отсылках к поп-культуре, которые он комментирует прямо посреди действия.","fact":"Голос Питера Гриффина в оригинале подарил персонажу сам создатель сериала Сет Макфарлейн.","wiki_en":"Peter Griffin"},{"name":"Эрик Картман","emoji":"🧥","meta":["«Южный парк»","вздорный школьник","1997"],"description":"Один из четырёх мальчишек из городка Саут-Парк, известный вспыльчивым характером, манипуляциями и постоянными эгоистичными планами обогащения. Его язвительные реплики и полное отсутствие такта делают его самым скандальным героем сериала.","fact":"Авторы сериала Трей Паркер и Мэтт Стоун озвучивают Картмана и большинство других персонажей сами.","wiki_en":"Eric Cartman"},{"name":"Рик Санчес","emoji":"🥼","meta":["«Рик и Морти»","безумный учёный","2013"],"description":"Циничный гениальный изобретатель, путешествующий по параллельным вселенным вместе с внуком Морти на построенном им самим космическом корабле. Его алкоголизм, чёрный юмор и презрение к любым нормам не мешают ему оставаться умнейшим существом мультивселенной.","fact":"Имя и характер персонажа отчасти пародируют доктора Эммета Брауна из «Назад в будущее».","wiki_en":"Rick Sanchez (Rick and Morty)"},{"name":"Бендер","emoji":"🤖","meta":["«Футурама»","робот-мошенник","1999"],"description":"Циничный человекоподобный робот из тридцатого века, по прямому назначению гнущий металлические балки и мечтающий о славе и лёгких деньгах. Его любовь к сигарам, пиву и мелким аферам сочетается с неожиданной преданностью друзьям — Филу Фраю и Лиле.","fact":"Полное имя персонажа — Бендер Сгибающая Родригес, а его серийный номер часто фигурирует в шутках сериала.","wiki_en":"Bender (Futurama)"},{"name":"Губка Боб Квадратные Штаны","emoji":"🧽","meta":["«Губка Боб»","неунывающая губка-повар","1999"],"description":"Жизнерадостная морская губка, работающая поваром в закусочной «Красти Краб» на дне Тихого океана и обожающая свою работу больше всего на свете. Его детская наивность постоянно сталкивается с ворчливым соседом Сквидвордом и лучшим другом Патриком.","fact":"Создатель сериала Стивен Хилленбург был морским биологом и аниматором ещё до его запуска.","wiki_en":"SpongeBob SquarePants (character)"},{"name":"Патрик Стар","emoji":"⭐","meta":["«Губка Боб»","простодушная морская звезда","1999"],"description":"Розовая морская звезда, живущая под камнем на дне океана и являющаяся лучшим другом Губки Боба. Его феноменальная глупость и странная логика регулярно приводят приятелей к нелепым, но забавным неприятностям.","fact":"Несмотря на постоянную демонстрацию тупости, в отдельных эпизодах Патрик неожиданно проявляет проблески гениальности.","wiki_en":"Patrick Star"},{"name":"Шрек","emoji":"👹","meta":["«Шрек»","добродушный людоед-огр","2001"],"description":"Ворчливый зелёный огр, желающий лишь одиночества в своём болоте, но втянутый в спасение принцессы ради возвращения покоя. Пародируя классические сказочные штампы, история о нём стала одной из самых кассовых анимационных франшиз в истории кино.","fact":"Персонаж основан на детской книге-картинке Уильяма Стайга, но во многом переосмыслен создателями студии.","wiki_en":"Shrek (character)"},{"name":"Осёл из «Шрека»","emoji":"🫏","meta":["«Шрек»","болтливый спутник огра","2001"],"description":"Неугомонный говорящий осёл, буквально не умолкающий ни на секунду и навязывающийся Шреку в лучшие друзья вопреки его желанию. Его бесконечная болтовня и добродушная наивность со временем становятся для сурового огра настоящей опорой.","fact":"Роль Осла озвучил комик Эдди Мёрфи, чья импровизация сильно повлияла на характер персонажа.","wiki_en":"Donkey (Shrek)"},{"name":"Кот в сапогах","emoji":"🐈","meta":["«Шрек»","отважный кот-наёмник","2004"],"description":"Обаятельный кот-фехтовальщик в сапогах и шляпе с пером, изначально подосланный убить Шрека, но ставший его верным спутником. Знаменитый трюк со слёзным взглядом огромных грустных глаз стал одной из самых узнаваемых сцен всей франшизы.","fact":"Персонаж вдохновлён классической европейской сказкой, но озвучен в стиле испанского авантюриста актёром Антонио Бандерасом.","wiki_en":"Puss in Boots (Shrek)"},{"name":"Базз Лайтер","emoji":"🚀","meta":["«История игрушек»","космический рейнджер-игрушка","1995"],"description":"Игрушечный космический рейнджер с выдвижными крыльями и лазером, искренне уверенный, что он настоящий герой, а не товар с полки магазина. Его соперничество, а затем дружба с ковбоем Вуди стали основой сюжета первого полнометражного мультфильма Pixar.","fact":"Фраза Базза «В бесконечность и дальше!» стала одним из самых узнаваемых слоганов студии Pixar.","wiki_en":"Buzz Lightyear"},{"name":"Шериф Вуди","emoji":"🤠","meta":["«История игрушек»","ковбой-игрушка","1995"],"description":"Тряпичный ковбой с вытяжным шнурком на спине, долгое время остававшийся любимой игрушкой мальчика Энди, пока не появился Базз Лайтер. Его тревога из-за потери привязанности хозяина и забота о друзьях-игрушках стали эмоциональным центром всей франшизы.","fact":"Голос Вуди во всех фильмах серии исполняет актёр Том Хэнкс.","wiki_en":"Woody (Toy Story)"},{"name":"Молния Маккуин","emoji":"🏎️","meta":["«Тачки»","самоуверенный гоночный болид","2006"],"description":"Юная и заносчивая гоночная машина, мечтающая о кубке чемпиона, но застрявшая в сонном придорожном городке Радиатор-Спрингс. Знакомство с его чудаковатыми жителями учит героя ценить дружбу больше личной славы.","fact":"Номер 95 на борту Молнии — отсылка к 1995 году, когда вышел первый полнометражный мультфильм Pixar.","wiki_en":"Lightning McQueen"},{"name":"ВАЛЛ-И","emoji":"🤖","meta":["«ВАЛЛ-И»","одинокий робот-уборщик","2008"],"description":"Маленький робот, сотни лет в одиночестве убирающий мусор на опустевшей Земле и коллекционирующий забавные человеческие находки. Встреча с гладким разведывательным роботом ЕВА меняет его тихую жизнь и судьбу всего человечества.","fact":"Почти половина фильма о нём обходится без единой произнесённой человеческой фразы.","wiki_en":"WALL-E"},{"name":"По из «Кунг-фу панды»","emoji":"🐼","meta":["«Кунг-фу панда»","неуклюжая панда-воин","2008"],"description":"Толстоватая и неуклюжая панда, работающая в лапшичной отца, но грезящая о кунг-фу и неожиданно избранная стать легендарным Драконьим воином. Вопреки насмешкам мастеров, его упорство и добродушие помогают ему стать настоящим героем долины.","fact":"Голос По в оригинальной версии озвучил актёр Джек Блэк.","wiki_en":"Po (Kung Fu Panda)"},{"name":"Миньоны","emoji":"🍌","meta":["«Гадкий я»","жёлтые существа-помощники","2010"],"description":"Маленькие жёлтые капсуловидные существа, тысячелетиями служащие самым разным злодеям и обожающие бананы больше всего на свете. Их тарабарский язык и хаотичная преданность хозяину сделали их одними из самых узнаваемых мультипликационных персонажей современности.","fact":"Речь миньонов представляет собой смесь реальных языков и придуманной бессмыслицы, которую озвучили сами режиссёры.","wiki_en":"Minions (Despicable Me)"},{"name":"Пикачу","emoji":"⚡","meta":["«Покемон»","электрический покемон-талисман","1996"],"description":"Жёлтое мышевидное существо, способное бить противников разрядами электричества, ставшее официальным лицом всей франшизы «Покемон». Верный спутник тренера Эша Кетчума, отказывающийся эволюционировать, чтобы остаться самим собой.","fact":"Имя Пикачу образовано от японских звукоподражаний писку мыши и искре электричества.","wiki_en":"Pikachu"},{"name":"Марио","emoji":"🍄","meta":["Nintendo","усатый водопроводчик-герой","1981"],"description":"Невысокий усатый итальянец-водопроводчик в красной кепке, раз за разом спасающий Принцессу Пич из лап дракона Боузера. Его прыжки, грибы силы и монеты стали основой самой продаваемой серии видеоигр в истории индустрии.","fact":"Изначально персонаж назывался просто Джампмен, а имя Марио получил в честь арендодателя офиса Nintendo в Америке.","wiki_en":"Mario"},{"name":"Соник","emoji":"💙","meta":["Sega","синий ёж-скороход","1991"],"description":"Ярко-синий ёж со сверхзвуковой скоростью бега, собирающий золотые кольца и противостоящий злому гению доктору Роботнику. Созданный как ответ Sega на популярность Марио, персонаж стал символом всей игровой платформы компании.","fact":"Нетерпеливое постукивание ногой стало фирменной анимацией Соника, если игрок долго ничего не делает.","wiki_en":"Sonic the Hedgehog (character)"},{"name":"Лара Крофт","emoji":"🏺","meta":["«Tomb Raider»","отважная расхитительница гробниц","1996"],"description":"Британская аристократка-археолог, исследующая древние гробницы и храмы по всему миру в поисках артефактов и опасных тайн. Её двойные пистолеты и атлетическая ловкость сделали её одной из первых по-настоящему культовых героинь видеоигр.","fact":"Ранние модели персонажа создавались с ограничениями графики того времени, из-за чего пропорции тела вызывали споры фанатов.","wiki_en":"Lara Croft"},{"name":"Геральт из Ривии","emoji":"⚔️","meta":["«Ведьмак», Анджей Сапковский","мутант-охотник на чудовищ","1986"],"description":"Профессиональный истребитель монстров, прошедший магические мутации ради нечеловеческой силы, скорости и белых волос. Его моральная неоднозначность и умение видеть оттенки серого между добром и злом сделали его одним из сложнейших героев современного фэнтези.","fact":"Персонаж впервые появился в рассказе польского писателя Анджея Сапковского, а не в компьютерной игре.","wiki_en":"Geralt of Rivia"},{"name":"Наруто Узумаки","emoji":"🍥","meta":["«Наруто»","юный ниндзя-изгой","1999"],"description":"Шумный и упрямый юный ниндзя деревни Конохи, с рождения носящий в себе печать могучего демона-лиса и мечтающий стать главой деревни. Его девиз никогда не сдаваться и верность друзьям сделали его одним из самых любимых героев современной манги.","fact":"Любимое блюдо персонажа — лапша рамэн — со временем стало неофициальным символом всей франшизы.","wiki_en":"Naruto Uzumaki"},{"name":"Сон Гоку","emoji":"🐒","meta":["«Жемчуг дракона»","инопланетный воин с хвостом","1984"],"description":"Простодушный и невероятно сильный боец инопланетного происхождения, растущий от наивного мальчика с обезьяньим хвостом до защитника всей Земли. Его бесконечное стремление стать сильнее и жажда честных поединков определили целый жанр приключенческой манги.","fact":"Персонаж во многом вдохновлён царём обезьян Сунь Укуном из классического китайского романа «Путешествие на Запад».","wiki_en":"Goku"},{"name":"Монки Д. Луффи","emoji":"🏴‍☠️","meta":["«Ван-Пис»","капитан пиратов из резины","1997"],"description":"Жизнерадостный капитан пиратской команды, тело которого после случайного съедения дьявольского фрукта стало тянуться, будто резина. Его мечта — найти легендарное сокровище Ван-Пис и стать королём пиратов — движет сюжетом одной из самых продаваемых манг в мире.","fact":"Соломенная шляпа Луффи — подарок пирата Шанкса, которому герой пообещал однажды её вернуть.","wiki_en":"Monkey D. Luffy"},{"name":"Сейлор Мун","emoji":"🌙","meta":["«Сейлор Мун»","девочка-воин в матроске","1991"],"description":"Обычная японская школьница, превращающаяся в отважную воительницу в матроске, чтобы защищать Землю от космических злодеев. Вместе с другими девушками-воительницами она сражается силой любви и лунной магии, что сделало сериал классикой жанра махо-сёдзё.","fact":"Соратницы героини названы в честь планет Солнечной системы, и от планеты зависят их магические силы.","wiki_en":"Sailor Moon (character)"},{"name":"Тоторо","emoji":"🌳","meta":["Studio Ghibli","добрый лесной дух","1988"],"description":"Огромный пушистый лесной дух, похожий на помесь совы и кота, которого видят только дети, случайно поселившиеся рядом с его лесом. Его молчаливая доброта и зонтик под дождём стали одним из самых узнаваемых образов японской анимации студии Ghibli.","fact":"Силуэт персонажа стал официальным логотипом самой студии Ghibli.","wiki_en":"My Neighbor Totoro"},{"name":"Hello Kitty","emoji":"🎀","meta":["Sanrio","белая кошечка с бантиком","1974"],"description":"Белая антропоморфная кошечка с красным бантиком на ухе, изображаемая всегда без рта, чтобы каждый мог додумать её настроение сам. Придуманная японской компанией Sanrio, она превратилась в один из самых узнаваемых и коммерчески успешных персонажей поп-культуры мира.","fact":"По официальной биографии Sanrio, персонаж — не кошка, а маленькая англичанка по имени Китти Уайт.","wiki_en":"Hello Kitty"},{"name":"Уолтер Уайт","emoji":"🧪","meta":["«Во все тяжкие»","учитель химии, ставший наркобароном","2008"],"description":"Скромный школьный учитель химии, после диагноза о смертельной болезни начинающий варить сверхчистый метамфетамин ради денег для семьи. Его постепенное превращение из тихого преподавателя в безжалостного главу наркоимперии стало одной из самых пронзительных трансформаций телевидения.","fact":"Псевдоним персонажа в преступном мире — Хайзенберг — отсылает к знаменитому физику-квантовику.","wiki_en":"Walter White (Breaking Bad)"},{"name":"Джесси Пинкман","emoji":"💰","meta":["«Во все тяжкие»","бывший ученик-напарник","2008"],"description":"Непутёвый бывший ученик Уолтера Уайта, втянутый учителем в производство метамфетамина и постепенно проходящий собственный болезненный путь. Несмотря на грубый жаргон и наивные ошибки, именно он сохраняет остатки совести на фоне морального падения напарника.","fact":"По первоначальному замыслу героя собирались убрать из сюжета уже в первом сезоне, но игра Аарона Пола изменила планы авторов.","wiki_en":"Jesse Pinkman"},{"name":"Тирион Ланнистер","emoji":"🍷","meta":["«Игра престолов»","остроумный карлик-Ланнистер","1996"],"description":"Циничный и невероятно начитанный представитель могущественного дома Ланнистеров, вынужденный всю жизнь бороться с презрением родни из-за своего роста. Его острый ум и умение находить выход из безнадёжных ситуаций сделали его одним из самых любимых персонажей саги.","fact":"Персонаж известен любовью к вину, а сыгравший его актёр Питер Динклэйдж получил за роль несколько премий «Эмми».","wiki_en":"Tyrion Lannister"},{"name":"Джон Сноу","emoji":"🐺","meta":["«Игра престолов»","бастард-командир Ночного дозора","1996"],"description":"Внебрачный сын лорда Севера, служащий в Ночном дозоре на краю известного мира и противостоящий угрозе из-за Стены. Его строгое чувство долга и раздираемая противоречиями судьба сделали его одним из центральных героев саги «Песнь льда и пламени».","fact":"Фраза «Ты ничего не знаешь, Джон Сноу» стала одной из самых цитируемых во всей франшизе.","wiki_en":"Jon Snow (character)"},{"name":"Дейенерис Таргариен","emoji":"🐉","meta":["«Игра престолов»","изгнанная принцесса-драконица","1996"],"description":"Последняя представительница свергнутой королевской династии, выросшая в изгнании и обретающая власть над тремя драконами. Её путь от бесправной девушки до могущественной правительницы, стремящейся вернуть трон предков, стал одной из центральных сюжетных линий саги.","fact":"Три дракона Дейенерис вылупились из окаменевших яиц, которые долгое время считались лишь древней реликвией.","wiki_en":"Daenerys Targaryen"},{"name":"Шелдон Купер","emoji":"🧮","meta":["«Теория большого взрыва»","эксцентричный физик-гений","2007"],"description":"Блестящий, но социально неловкий физик-теоретик, живущий по строгому расписанию и собственным непреклонным правилам поведения. Его непонимание сарказма, страсть к комиксам и фирменное место на диване стали источником большинства шуток сериала.","fact":"Фирменный ритуал персонажа — троекратный стук в дверь с повторением имени того, к кому он пришёл.","wiki_en":"Sheldon Cooper"},{"name":"Доктор Грегори Хаус","emoji":"🦯","meta":["«Доктор Хаус»","циничный врач-диагност","2004"],"description":"Гениальный, но невыносимо циничный диагност, хромающий из-за старой травмы ноги и предпочитающий грубую честность вежливой лжи. Его нестандартные методы лечения и знаменитая фраза о том, что все лгут, сделали сериал одной из самых узнаваемых медицинских драм.","fact":"Персонаж во многом задуман как современная версия Шерлока Холмса, только в медицинском антураже.","wiki_en":"Gregory House"},{"name":"Майкл Скотт","emoji":"🗂️","meta":["«Офис» (США)","неловкий начальник филиала","2005"],"description":"Директор захолустного филиала бумажной компании, отчаянно пытающийся быть другом всем сотрудникам, но постоянно попадающий впросак. Его неуместные шутки и наивное желание нравиться делают его одновременно самым неловким и трогательным боссом на телевидении.","fact":"Персонаж основан на британском оригинале сериала «Офис», где похожего начальника играл Рики Джервейс.","wiki_en":"Michael Scott (The Office)"},{"name":"Джоуи Триббиани","emoji":"🍕","meta":["«Друзья»","простодушный актёр-красавчик","1994"],"description":"Обаятельный, но не самый сообразительный нью-йоркский актёр, готовый на всё ради роли и категорически не умеющий делиться едой. Его фирменная фраза-знакомство с девушками и трогательная преданность друзьям сделали его одним из самых любимых героев культового ситкома.","fact":"После финала «Друзей» о персонаже сняли отдельный сериал «Джоуи», продержавшийся два сезона.","wiki_en":"Joey Tribbiani"},{"name":"Декстер Морган","emoji":"🔪","meta":["«Декстер»","серийный убийца-судмедэксперт","2006"],"description":"Эксперт по анализу крови в полиции Майами, скрывающий под маской обходительности тщательно контролируемые убийственные наклонности. Следуя строгому «кодексу» приёмного отца, он убивает только других убийц, ускользнувших от правосудия, балансируя между двумя жизнями.","fact":"Персонаж впервые появился в серии книг писателя Джеффа Линдсея, а не был придуман для телевидения.","wiki_en":"Dexter Morgan"},{"name":"Томас Шелби","emoji":"🎩","meta":["«Острые козырьки»","глава бирмингемской банды","2013"],"description":"Харизматичный и расчётливый лидер криминальной семьи Шелби, прошедший через окопы Первой мировой войны и превративший уличную банду в настоящую империю. Фирменные твидовые кепки его банды дали название всей франшизе.","fact":"Роль сыграл Киллиан Мёрфи, а банда с таким прозвищем действительно существовала в Бирмингеме на рубеже XIX–XX веков.","wiki_en":"Thomas Shelby"},{"name":"Одиннадцать из «Очень странных дел»","emoji":"🧇","meta":["«Очень странные дела»","девочка с телекинезом","2016"],"description":"Загадочная девочка с бритой головой и номером на запястье, сбежавшая из секретной лаборатории и обладающая мощными телекинетическими способностями. Её дружба с компанией подростков из городка Хокинс и любовь к вафлям стали центром культового фантастического сериала.","fact":"Персонажа сыграла юная актриса Милли Бобби Браун, для роли которой ей пришлось полностью обрить голову.","wiki_en":"Eleven (Stranger Things)"},{"name":"Уэнздей Аддамс","emoji":"🖤","meta":["«Семейка Аддамс»","мрачная девочка-готка","1938"],"description":"Бледная и невозмутимая девочка из семьи, обожающей всё жуткое и мрачное, воспринимающая пытки и похороны как обычное развлечение. Её ледяной сарказм и полное отсутствие эмоций на лице сделали её одной из самых узнаваемых готических героинь поп-культуры.","fact":"Персонаж впервые появился в газетных комиксах художника Чарльза Аддамса, где изначально даже не имел имени.","wiki_en":"Wednesday Addams"},{"name":"Мистер Бин","emoji":"🧸","meta":["«Мистер Бин»","неуклюжий молчаливый чудак","1990"],"description":"Нелепый и почти всегда молчаливый чудак, постоянно попадающий в комичные ситуации из-за собственной неуклюжести и странной логики. Его верным спутником остаётся плюшевый медвежонок Тедди, а фирменный жёлтый автомобиль стал узнаваемой деталью образа.","fact":"Актёр Роуэн Аткинсон создавал персонажа так, чтобы шутки были понятны зрителям в любой стране без перевода.","wiki_en":"Mr. Bean"},{"name":"Барби","emoji":"👱‍♀️","meta":["Mattel","кукла-икона моды","1959"],"description":"Стройная кукла с безупречным гардеробом и десятками профессий — от астронавта до президента, — придуманная американской компанией Mattel. За десятилетия она стала не только самой продаваемой игрушкой в мире, но и предметом споров об идеалах женской красоты.","fact":"Полное имя куклы по легенде бренда — Барбара Миллисент Робертс.","wiki_en":"Barbie"},{"name":"Оптимус Прайм","emoji":"🚛","meta":["«Трансформеры»","лидер роботов-автоботов","1984"],"description":"Благородный предводитель расы роботов-автоботов, способных превращаться в технику, чаще всего изображаемый в облике синего грузовика. Его многолетняя война со злодейским Мегатроном и десептиконами стала основой одной из самых долгоживущих игрушечных франшиз.","fact":"Классический голос персонажа в мультсериале и первых фильмах принадлежал актёру Питеру Каллену.","wiki_en":"Optimus Prime"},{"name":"Черепашки-ниндзя","emoji":"🐢","meta":["TMNT","мутанты-воины боевых искусств","1984"],"description":"Четверо антропоморфных черепах-мутантов, обученных боевым искусствам мудрой крысой-сенсеем и живущих в канализации Нью-Йорка. Названные в честь художников Возрождения, они сражаются с преступностью, обожая при этом обычную пиццу.","fact":"Персонажи впервые появились в независимом чёрно-белом комиксе, задуманном как пародия на другие супергеройские команды.","wiki_en":"Teenage Mutant Ninja Turtles"},{"name":"Чебурашка","emoji":"🧸","meta":["Эдуард Успенский","неизвестный науке зверёк","1966"],"description":"Странное ушастое существо неизвестного науке вида, найденное в ящике с апельсинами и поселившееся в телефонной будке. Его дружба с крокодилом Геной и строительство Дома дружбы стали любимой историей нескольких поколений советских и российских детей.","fact":"Имя персонажу дали за его привычку постоянно падать и чебурахаться от неуклюжести.","wiki_en":"Cheburashka"},{"name":"Крокодил Гена","emoji":"🐊","meta":["Эдуард Успенский","работающий в зоопарке крокодил","1966"],"description":"Интеллигентный крокодил, устроившийся работать крокодилом в зоопарке и играющий на гармошке по вечерам от одиночества. Именно его объявление о поиске друзей приводит к знакомству с Чебурашкой, положившему начало их долгой дружбе.","fact":"Песня Гены о том, что день рождения бывает только раз в году, стала одной из самых узнаваемых мелодий советской мультипликации.","wiki_en":"Gena the Crocodile"},{"name":"Волк из «Ну, погоди!»","emoji":"🚬","meta":["«Ну, погоди!»","незадачливый хулиган-волк","1969"],"description":"Хулиганистый волк в тельняшке, бесконечно и безуспешно пытающийся поймать быстрого и сообразительного Зайца. Практически без единого слова диалога сериал стал одной из самых узнаваемых советских мультипликационных классик.","fact":"Коронную фразу «Ну, заяц, погоди!» волк произносит почти в каждой серии, дав название всему сериалу.","wiki_en":"Nu, Pogodi!"},{"name":"Кот Матроскин","emoji":"🐄","meta":["Эдуард Успенский","хозяйственный деревенский кот","1974"],"description":"Рассудительный говорящий кот, поселившийся в деревне Простоквашино вместе с мальчиком дядей Фёдором и его родителями. Его практичность, любовь к корове Мурке и знаменитая фраза о совместном труде сделали его одним из самых узнаваемых героев советской мультипликации.","fact":"В мультфильмах о Простоквашино голосом Матроскина говорит актёр Олег Табаков.","wiki_en":"Three from Prostokvashino"},{"name":"Незнайка","emoji":"🎩","meta":["Николай Носов","хвастливый коротышка-выдумщик","1954"],"description":"Незадачливый и хвастливый коротышка из Цветочного города, вечно берущийся за дела, в которых ничего не смыслит. Его многочисленные неудачи и приключения в трилогии Николая Носова учат маленьких читателей на собственных ошибках героя.","fact":"В заключительной части трилогии, «Незнайка на Луне», коротышки отправляются в космос и попадают в мир денег и наживы.","wiki_en":"Dunno"},{"name":"Буратино","emoji":"🪵","meta":["Алексей Толстой","деревянный длинноносый мальчик","1936"],"description":"Озорной деревянный мальчик с длинным носом, вырезанный старым шарманщиком Папой Карло из говорящего полена. Его золотой ключик и приключения в компании кота Базилио и лисы Алисы стали классикой советской детской литературы.","fact":"Повесть Алексея Толстого создана как переосмысление итальянской сказки о Пиноккио на русский лад.","wiki_en":"Buratino"},{"name":"Доктор Айболит","emoji":"🩹","meta":["Корней Чуковский","добрый доктор для зверей","1929"],"description":"Добрейший доктор, лечащий зверей со всего света и отправляющийся в Африку спасать заболевших слонов, бегемотов и шакалов. Его готовность прийти на помощь любому существу сделала его символом бескорыстной доброты в советской детской литературе.","fact":"Прообразом доброго доктора считают знакомого Чуковского — виленского врача Цемаха Шабада, лечившего бедняков бесплатно.","wiki_en":"Aybolit"},{"name":"Баба-яга","emoji":"🧙‍♀️","meta":["русский фольклор","лесная ведьма-колдунья","до XVIII века"],"description":"Таинственная старуха-колдунья, живущая в глубине леса в избушке на курьих ножках и летающая в ступе с метлой. В зависимости от сказки она то помогает герою мудрым советом, то становится главной угрозой, которую нужно перехитрить.","fact":"Избушка на курьих ножках в сказках разворачивается к герою только после произнесения особого заклинания.","wiki_en":"Baba Yaga"},{"name":"Кощей Бессмертный","emoji":"🥚","meta":["русский фольклор","бессмертный злой чародей","до XVIII века"],"description":"Худой и злобный колдун из русских сказок, чья смерть спрятана на конце иглы, находящейся внутри цепочки из яйца, утки и зайца. Похититель царевен и извечный противник сказочных богатырей, он стал символом зла, которое невозможно победить обычным способом.","fact":"Само слово «кощей» в старину означало худого, костлявого человека или пленника.","wiki_en":"Koschei"},{"name":"Илья Муромец","emoji":"🛡️","meta":["русские былины","богатырь-защитник Руси","до XIII века"],"description":"Могучий крестьянский сын, тридцать три года пролежавший на печи без движения, прежде чем чудесным образом обрёл богатырскую силу. Ставший главным защитником Киевской Руси в русских былинах, он остаётся образцом воинской доблести и справедливости.","fact":"Прообразом былинного богатыря считают реального монаха Илью Печерского, чьи мощи хранятся в Киево-Печерской лавре.","wiki_en":"Ilya Muromets"},{"name":"Колобок","emoji":"🟡","meta":["русская сказка","круглый беглец из теста","до XIX века"],"description":"Круглый румяный колобок, слепленный старухой из остатков муки и сбежавший прямо с подоконника от дедушки и бабушки. По дороге он поочерёдно уходит от зайца, волка и медведя, распевая хвастливую песенку, но в итоге попадается хитрой лисе.","fact":"Похожие сюжеты о съедобном беглеце встречаются в фольклоре многих народов мира, включая знаменитого английского пряничного человечка.","wiki_en":"Kolobok"},{"name":"Остап Бендер","emoji":"🕶️","meta":["Ильф и Петров","великий комбинатор-авантюрист","1928"],"description":"Обаятельный жулик и великий комбинатор, знающий, по его собственным словам, четыреста относительно честных способов отъёма денег. Его поиски бриллиантов, спрятанных в одном из двенадцати стульев, стали одной из самых любимых сатирических историй советской литературы.","fact":"Многие афоризмы персонажа, вроде фразы про лёд, который тронулся, давно живут в русском языке отдельно от романа.","wiki_en":"Ostap Bender"},{"name":"Штирлиц","emoji":"🕵️","meta":["Юлиан Семёнов","советский разведчик в Рейхе","1969"],"description":"Советский разведчик, много лет действующий под личиной высокопоставленного офицера СС в нацистской Германии. Его хладнокровие и умение просчитывать ходы противника сделали его, пожалуй, самым известным шпионом советской культуры.","fact":"Персонаж стал героем огромного количества анекдотов, обыгрывающих его невозмутимость в любых ситуациях.","wiki_en":"Stierlitz"},{"name":"Данила Багров","emoji":"🎧","meta":["«Брат»","ветеран-одиночка в Петербурге","1997"],"description":"Вернувшийся из армии молодой человек, оказывающийся втянутым в криминальные разборки старшего брата в Петербурге девяностых. Его немногословность, собственное понимание справедливости и плеер с музыкой группы «Наутилус Помпилиус» сделали его одним из символов постсоветского кино.","fact":"Реплика персонажа о том, в чём сила, давно стала крылатой фразой, живущей отдельно от фильма.","wiki_en":"Brother (1997 film)"},{"name":"Шурик","emoji":"📸","meta":["комедии Леонида Гайдая","простодушный студент-очкарик","1965"],"description":"Скромный и любознательный студент в очках, попадающий в череду комичных ситуаций — от стройотряда до случайного знакомства с похитителями невесты. Его наивная честность на фоне окружающих проходимцев стала визитной карточкой нескольких культовых советских комедий.","fact":"Один и тот же актёр Александр Демьяненко играл персонажа под этим именем в нескольких разных фильмах Гайдая.","wiki_en":"Operation Y and Other Shurik's Adventures"},{"name":"Товарищ Сухов","emoji":"🏜️","meta":["«Белое солнце пустыни»","красноармеец в пустыне","1970"],"description":"Демобилизованный красноармеец, мечтающий вернуться домой к жене, но вынужденный по пути присматривать за гаремом сбежавшего басмача. Его спокойная рассудительность и письма к далёкой Катерине Матвеевне стали одними из самых цитируемых образов советского кино.","fact":"Фильм традиционно смотрят российские космонавты перед стартом ракеты как часть предполётного ритуала.","wiki_en":"White Sun of the Desert"},{"name":"Глеб Жеглов","emoji":"🚔","meta":["«Место встречи изменить нельзя»","жёсткий оперативник МУРа","1979"],"description":"Бескомпромиссный оперативник московского уголовного розыска послевоенных лет, готовый ради поимки преступника переступить через формальности закона. Его спор с молодым напарником о том, оправдывает ли цель средства, стал одной из главных тем культового телефильма.","fact":"Роль Жеглова сыграл Владимир Высоцкий, для которого эта работа стала одной из последних перед смертью.","wiki_en":"The Meeting Place Cannot Be Changed"},{"name":"Евгений Онегин","emoji":"🎭","meta":["Александр Пушкин","пресыщенный светский денди","1833"],"description":"Разочарованный в жизни молодой дворянин, отвергающий искреннюю любовь провинциальной барышни Татьяны ради холодной светской скуки. Его внутренняя пустота и запоздалое раскаяние сделали персонажа образцом так называемого «лишнего человека» в русской литературе.","fact":"Роман в стихах Пушкин писал более семи лет, постепенно меняя первоначальный замысел сюжета.","wiki_en":"Eugene Onegin"},{"name":"Родион Раскольников","emoji":"🪓","meta":["Достоевский","студент-теоретик-убийца","1866"],"description":"Бедный петербургский студент, решающийся на убийство старухи-процентщицы ради проверки собственной теории о праве сильной личности. Его мучительные внутренние терзания после преступления составляют психологическое ядро одного из главных романов Достоевского.","fact":"Теория персонажа о разделении людей на «обыкновенных» и «право имеющих» стала предметом бесчисленных философских споров.","wiki_en":"Rodion Raskolnikov"},{"name":"Анна Каренина","emoji":"🚂","meta":["Лев Толстой","светская дама в трагической любви","1877"],"description":"Замужняя аристократка из высшего петербургского общества, чья страстная любовь к офицеру Вронскому оборачивается конфликтом с семьёй и осуждением света. Её трагическая судьба стала одним из самых известных исследований темы любви и морали в мировой литературе.","fact":"Знаменитая первая фраза романа о счастливых и несчастливых семьях давно стала самостоятельным афоризмом.","wiki_en":"Anna Karenina"},{"name":"Воланд","emoji":"🐾","meta":["«Мастер и Маргарита»","загадочный дьявол-профессор","1966"],"description":"Таинственный иностранный профессор чёрной магии, прибывающий в Москву тридцатых годов со свитой демонов, чтобы вершить своеобразное правосудие. Его знаменитая фраза о том, что рукописи не горят, стала одной из самых узнаваемых цитат русской литературы.","fact":"Роман Булгакова был опубликован лишь спустя десятилетия после смерти автора, сначала в сильно сокращённом виде.","wiki_en":"Woland"},{"name":"Кот Бегемот","emoji":"🐱","meta":["«Мастер и Маргарита»","демон-кот-оборотень","1966"],"description":"Огромный чёрный кот из свиты Воланда, способный превращаться в упитанного человека и обожающий шахматы и дерзкие шутки. Его проделки в советской Москве, вроде поездки на трамвае и стрельбы из револьвера, стали одними из самых запоминающихся сцен романа.","fact":"Имя персонажа отсылает к библейскому чудовищу Бегемоту, упоминаемому в Книге Иова.","wiki_en":"Behemoth (The Master and Margarita)"},{"name":"Маша из «Маши и Медведя»","emoji":"🐻","meta":["«Маша и Медведь»","неугомонная девочка-озорница","2009"],"description":"Энергичная и неугомонная девочка, поселившаяся по соседству с добродушным, но уставшим от её проказ цирковым Медведем. Её бесконечная энергия и умение превращать любую ситуацию в хаос сделали российский мультсериал популярным далеко за пределами страны.","fact":"Отдельные серии мультсериала на YouTube набрали миллиарды просмотров, а сам он переведён на десятки языков.","wiki_en":"Masha and the Bear"},{"name":"Крош из «Смешариков»","emoji":"🐰","meta":["«Смешарики»","энергичный заяц-непоседа","2004"],"description":"Импульсивный и вечно куда-то спешащий круглый заяц, обожающий спорт и рискованные затеи больше, чем спокойные размышления. Один из главных героев российского мультсериала о круглых зверятах, ставшего заметным явлением отечественной анимации нулевых.","fact":"Дизайн всех героев построен на круге, а название сериала соединяет слова «смешные» и «шарики».","wiki_en":"Smeshariki"},{"name":"Лунтик","emoji":"🌕","meta":["«Лунтик»","малыш, упавший с Луны","2006"],"description":"Пушистое существо, родившееся на Луне и случайно упавшее на Землю прямо в лесной пруд, где его находят и воспитывают насекомые. Его добродушное удивление всему новому и дружба с лесными обитателями сделали сериал одним из самых популярных российских мультфильмов для малышей.","fact":"Имя персонажа образовано напрямую от слова «луна», откуда он, по сюжету, и появился.","wiki_en":"Luntik"},{"name":"Дядя Стёпа","emoji":"📏","meta":["Сергей Михалков","добрый великан-постовой","1935"],"description":"Невероятно высокий и добродушный великан из стихов Сергея Михалкова, который в продолжениях становится постовым милиционером. Его готовность прийти на помощь — от спасения утопающих до тушения пожаров — сделала его образцом положительного героя советской детской поэзии.","fact":"Михалков писал о дяде Стёпе почти полвека — от первого стихотворения тридцатых годов до поздней части о герое-ветеране.","wiki_en":"Uncle Styopa"},{"name":"Старик Хоттабыч","emoji":"🧞","meta":["Лазарь Лагин","древний джинн из кувшина","1938"],"description":"Могущественный джинн, тысячи лет проведший заточённым в глиняном кувшине и освобождённый советским школьником Волькой. Его старомодная восточная речь и наивные попытки понять устройство советской жизни стали основой для множества комичных ситуаций.","fact":"Повесть во многом вдохновлена английской книгой о джинне, но действие перенесено в советскую Москву.","wiki_en":"Old Man Hottabych"},{"name":"Электроник","emoji":"🔌","meta":["Евгений Велтистов","мальчик-робот-двойник","1964"],"description":"Робот-мальчик, внешне неотличимый от школьника Серёжи Сыроежкина, с фотографии которого его и создали, из-за чего мальчишки меняются местами. Его дружба с ребятами и постепенное обретение почти человеческих чувств стали основой знаменитой советской повести и фильма.","fact":"Песня «Крылатые качели» из телефильма о персонаже стала одной из самых узнаваемых советских детских песен.","wiki_en":"The Adventures of Elektronik"}];
